const USER="a".repeat(32),OTHER="b".repeat(32),KEY=Buffer.alloc(32,7),SALT=Buffer.alloc(16,3),origin=canonicalOrigin(DEFAULT_BASE_URL),scope=Buffer.from(`${origin}\0${USER}`).toString("base64url"),slot=(id:string)=>`${ACCOUNT_STORAGE_PREFIX.audioQueue}${origin}:${USER}:${id}`;
