 status=200;uploads=[];parentPresent=false;envelopeStatus=404;envelope=null;await api.setSession("native-bearer",USER,"alice");await api.cacheSalt("alice",SALT.toString("base64"));vault.unlock({masterKey:Buffer.alloc(32),authKey:Buffer.alloc(32,2),dataKey:Buffer.from(KEY)},USER);
 vi.stubGlobal("fetch",async(url:string,init:RequestInit)=>{const path=new URL(url).pathname;let value:unknown={},code=200;if(path.endsWith("/audio/attachments")){if(status===200)uploads.push(JSON.parse(String(init.body)));code=status;value=code===200?{}:{detail:"native attachment refused"};}else if(path.endsWith("/auth/key-envelope")){code=envelopeStatus;value=envelope??{detail:"legacy envelope endpoint absent"};}else if(path.includes("/entries/")){code=parentPresent?200:404;value=parentPresent?{id:"server-entry",client_entry_id:path.split("/").at(-1),blob:"",entry_date:"2026-10-07",content_version:1}:{detail:"parent has not committed"};}else throw new Error("unexpected native route "+path);const response=new Response(JSON.stringify(value),{status:code});Object.defineProperty(response,"url",{value:url});return response;});
