async function keep(id="recording",options:{parentPending?:boolean,durationSeconds?:number}={}){const blob=encryptAudio({dataKey:KEY},USER,id,Buffer.from("the user's retained spoken words"));await enqueueAudio({userId:USER,clientEntryId:id,...blob,mime:"audio/m4a",durationSeconds:options.durationSeconds??4,parentPending:options.parentPending},captureLocalWritePermit(USER,KEY));return blob.blobB64;}
async function descriptor(id="recording"){return JSON.parse((await storage.getItem(slot(id)))!);}
it("reports the exact saved revision and native timestamp while retaining authenticated ciphertext",async()=>{const blob=await keep();const row=await descriptor();expect(await listSavedAudio(USER)).toEqual([{id:"recording",queuedAt:row.queuedAt,needsAttention:false,revision:row.revision}]);expect(await audioQueueStatus(USER)).toEqual({total:1,needsAttention:0});expect(await fs.readAsStringAsync(row.uri)).toBe(blob);expect(row).toMatchObject({v:2,scope,mime:"audio/m4a",durationSeconds:4});});
