it.each(["foreign scope","scope punctuation","wrong root","suffix traversal","missing revision"])("refuses an unsafe native file descriptor (%s) while preserving every unrelated file",async mode=>{await keep();const row=await descriptor(),unrelated=fs.documentDirectory+"unrelated-file";fs.__seedFile(unrelated,"another application's file");if(mode==="foreign scope")row.scope=Buffer.from("foreign").toString("base64url");if(mode==="scope punctuation")row.scope=scope+".";if(mode==="wrong root")row.uri=unrelated;if(mode==="suffix traversal")row.uri=row.uri+"/../unrelated-file";if(mode==="missing revision")delete row.revision;await storage.setItem(slot("recording"),JSON.stringify(row));expect(await listSavedAudio(USER)).toEqual([{id:"recording",queuedAt:0,needsAttention:true,revision:undefined}]);expect(await flushAudioQueue()).toBe(0);expect(fs.__hasFile(unrelated)).toBe(true);});
