it("accepts the exact retained byte bound as authenticated audio and rejects one byte more",async()=>{const id="bounded",blob=encryptAudio({dataKey:KEY},USER,id,Buffer.alloc(4_499_972,9));expect(blob.blobB64.length).toBe(MAX_TAKE_BYTES);await enqueueAudio({userId:USER,clientEntryId:id,...blob,mime:"audio/m4a",durationSeconds:0},captureLocalWritePermit(USER,KEY));expect(await listSavedAudio(USER)).toMatchObject([{id,needsAttention:false}]);expect(await flushAudioQueue()).toBe(1);expect(decryptAudio({dataKey:KEY},USER,id,String(uploads[0]!.blob))).toEqual(Buffer.alloc(4_499_972,9));await expect(enqueueAudio({userId:USER,clientEntryId:"too-large",blobB64:blob.blobB64+"x",mime:"audio/m4a",durationSeconds:0},captureLocalWritePermit(USER,KEY))).rejects.toBeInstanceOf(AudioTooLargeError);},120000);
it.each([-1,Infinity,NaN])("refuses an invalid native recording duration %j before retaining a descriptor",async duration=>{await expect(keep("bad-duration",{durationSeconds:duration})).rejects.toThrow("Invalid recording");expect(await audioQueueCount(USER)).toBe(0);});
it("removes a partial native ciphertext file after its write fails",async()=>{const write=fs.writeAsStringAsync.getMockImplementation()!;fs.writeAsStringAsync.mockImplementation(async(uri,value,...args)=>{await write(uri,value,...args);throw new Error("native ciphertext disk full");});await expect(keep()).rejects.toThrow("native ciphertext disk full");expect(await listSavedAudio(USER)).toEqual([]);for(const[uri]of fs.writeAsStringAsync.mock.calls)expect(fs.__hasFile(uri)).toBe(false);});
