it("migrates a legacy native blob only after file completion and uploads its exact authored metadata",async()=>{const blob=encryptAudio({dataKey:KEY},USER,"legacy",Buffer.from("legacy spoken words"));await storage.setItem(slot("legacy"),JSON.stringify({...blob,mime:"audio/m4a",durationSeconds:0,queuedAt:123}));expect(await flushAudioQueue()).toBe(1);expect(uploads).toEqual([{client_entry_id:"legacy",blob:blob.blobB64,mime:"audio/m4a",duration_seconds:0}]);expect(await listSavedAudio(USER)).toEqual([]);});
