it("exports a complete native legacy bundle whose ciphertext opens independently and preserves custody",async()=>{const blob=await keep();await exportSavedAudio(USER,"recording");const uri=sharing.shareAsync.mock.calls[0]![0],bundle=JSON.parse(await fs.readAsStringAsync(uri)),row=await descriptor();expect(bundle).toEqual({version:2,user_id:USER,username:"alice",salt:SALT.toString("base64"),key_scheme:"v1",kdf_params:null,wrapped_data_key:null,entries:[],insights:[],measures:[],audio:[{client_entry_id:"recording",blob,mime_type:"audio/m4a",duration_seconds:4,content_version:1,created_at:new Date(row.queuedAt).toISOString()}]});expect(decryptAudio({dataKey:KEY},USER,"recording",bundle.audio[0].blob)).toEqual(Buffer.from("the user's retained spoken words"));expect(await audioQueueCount(USER)).toBe(1);await removeSavedAudio(USER,"recording",row.revision);expect(fs.__hasFile(uri)).toBe(false);expect(fs.__hasFile(row.uri)).toBe(false);expect(await listSavedAudio(USER)).toEqual([]);});
it("exports the current native v2 envelope with independently usable unlock parameters",async()=>{
 await keep();const password="the exported account's actual password",params={algorithm:"pbkdf2-sha256",version:1,iterations:600000} as const,salt=SALT.toString("base64"),master=crypto.pbkdf2Sync(password,SALT,params.iterations,32,"sha256"),kek=Buffer.from(crypto.hkdfSync("sha256",master,SALT,Buffer.from("mindpattern/envelope/v2"),32)),nonce=Buffer.alloc(12,6),cipher=crypto.createCipheriv("aes-256-gcm",kek,nonce);cipher.setAAD(Buffer.from(JSON.stringify({context:"envelope",kdf_params:params,username:"alice"})));const wrapped=Buffer.concat([nonce,cipher.update(KEY),cipher.final(),cipher.getAuthTag()]).toString("base64");
 await cacheEnvelope("alice",{scheme:"v2",saltB64:salt,kdfParams:params,wrappedB64:wrapped});await exportSavedAudio(USER,"recording");const uri=sharing.shareAsync.mock.calls[0]![0],bundle=JSON.parse(await fs.readAsStringAsync(uri));expect(bundle).toMatchObject({key_scheme:"v2",kdf_params:params,wrapped_data_key:wrapped,salt,user_id:USER});
 const freshMaster=crypto.pbkdf2Sync(password,Buffer.from(bundle.salt,"base64"),bundle.kdf_params.iterations,32,"sha256"),freshKek=Buffer.from(crypto.hkdfSync("sha256",freshMaster,Buffer.from(bundle.salt,"base64"),Buffer.from("mindpattern/envelope/v2"),32)),envelopeBytes=Buffer.from(bundle.wrapped_data_key,"base64"),decipher=crypto.createDecipheriv("aes-256-gcm",freshKek,envelopeBytes.subarray(0,12));decipher.setAAD(Buffer.from(JSON.stringify({context:"envelope",kdf_params:bundle.kdf_params,username:bundle.username})));decipher.setAuthTag(envelopeBytes.subarray(-16));const freshData=Buffer.concat([decipher.update(envelopeBytes.subarray(12,-16)),decipher.final()]);expect(decryptAudio({dataKey:freshData},bundle.user_id,bundle.audio[0].client_entry_id,bundle.audio[0].blob)).toEqual(Buffer.from("the user's retained spoken words"));expect(await audioQueueCount(USER)).toBe(1);master.fill(0);kek.fill(0);freshMaster.fill(0);freshKek.fill(0);freshData.fill(0);
});
