 vi.useFakeTimers({toFake:["Date"]});vi.setSystemTime(10_000);try{await keep();status=failure;expect(await flushAudioQueue()).toBe(0);const row=await descriptor();expect(row.notBefore).toBe(910_000);status=200;expect(await flushAudioQueue()).toBe(0);vi.setSystemTime(909_999);expect(await flushAudioQueue()).toBe(0);vi.setSystemTime(910_000);expect(await flushAudioQueue()).toBe(1);expect(decryptAudio({dataKey:KEY},USER,"recording",String(uploads[0]!.blob))).toEqual(Buffer.from("the user's retained spoken words"));}finally{vi.useRealTimers();}
