async function physicalDirectoryVolume(){
 const volume=await nativeVolume.mkdtemp(join(tmpdir(),"mindpattern-audio-native-directory-"));const physical=(uri:string)=>join(volume,uri.slice(fs.documentDirectory.length));
 fs.makeDirectoryAsync.mockImplementation(async(uri:string,options?:{intermediates?:boolean})=>{if(!uri.startsWith(fs.documentDirectory))throw new Error("native directory is outside the app volume");await nativeVolume.mkdir(physical(uri),{recursive:options?.intermediates===true});});
 return {physical,cleanup:()=>nativeVolume.rm(volume,{recursive:true,force:true})};
}
it("creates the account's physical native recording directory on a fresh device volume",async()=>{
 const volume=await physicalDirectoryVolume();try{const blob=await keep(),row=await descriptor();expect((await nativeVolume.stat(volume.physical(row.uri.slice(0,row.uri.lastIndexOf("/")+1)))).isDirectory()).toBe(true);expect(await fs.readAsStringAsync(row.uri)).toBe(blob);expect(await audioQueueCount(USER)).toBe(1);}finally{await volume.cleanup();}
});
it("permits a second native ciphertext export into the account's existing physical share directory",async()=>{
 const volume=await physicalDirectoryVolume();try{await keep();await exportSavedAudio(USER,"recording");await exportSavedAudio(USER,"recording");expect(sharing.shareAsync.mock.calls).toHaveLength(2);const uri=sharing.shareAsync.mock.calls[1]![0];expect((await nativeVolume.stat(volume.physical(uri.slice(0,uri.lastIndexOf("/")+1)))).isDirectory()).toBe(true);expect(JSON.parse(await fs.readAsStringAsync(uri)).audio).toHaveLength(1);expect(await audioQueueCount(USER)).toBe(1);}finally{await volume.cleanup();}
});
